/**
 * The service worker's URL parsing, checked against routes Python produces.
 *
 * This is a platform boundary rather than an algorithm: if the two sides
 * disagree on where a route ends and a chunk key begins, the only symptom is
 * blank tiles in the viewer. `fixtures.json` is generated by
 * `tests/browser/dump_route_fixtures.py`, so the expectations here come from
 * the real Python implementation.
 *
 *   node --test tests/browser/routes.test.mjs
 */

import assert from "node:assert/strict";
import { createRequire } from "node:module";
import { readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import test from "node:test";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(here, "..", "..");

const require = createRequire(import.meta.url);
const routes = require(join(repoRoot, "docs", "browser", "routes.js"));

const fixtures = JSON.parse(readFileSync(join(here, "fixtures.json"), "utf8"));

test("requests outside the service worker prefix are ignored", () => {
  assert.equal(routes.parseRequest("/multiview-stitcher/browser/app.js"), null);
  assert.equal(routes.parseRequest("/neuroglancer/index.html"), null);
});

test("the prefix is matched anywhere, so sub-path deployments work", () => {
  for (const base of ["", "/multiview-stitcher", "/multiview-stitcher/main/browser"]) {
    assert.deepEqual(routes.parseRequest(`${base}/__mvs__/fs/abc/x/.zattrs`), {
      kind: "fs",
      path: "abc/x/.zattrs",
    });
  }
});

test("file paths split into a mount and a relative path", () => {
  assert.deepEqual(routes.parseFilePath("a1b2c3d4/tile_0.ome.zarr/0/0/0/0/0"), {
    mount: "a1b2c3d4",
    path: "tile_0.ome.zarr/0/0/0/0/0",
  });
  assert.equal(routes.parseFilePath("no-slash"), null);
});

test("virtual OME-Zarr paths split at the route suffix", () => {
  for (const { route, key, path } of fixtures.zarr_requests) {
    assert.deepEqual(
      routes.parseZarrPath(path),
      { route, key },
      `parsing ${path}`,
    );
  }
});

test("routes generated by Python round-trip through the full request path", () => {
  for (const { route, key, path } of fixtures.zarr_requests) {
    const request = routes.parseRequest(`/app/__mvs__/zarr/${path}`);
    assert.equal(request.kind, "zarr");

    const parsed = routes.parseZarrPath(request.path);
    assert.equal(parsed.route, route);
    assert.equal(parsed.key, key);
  }
});

test("a route from a retired generation is still parseable", () => {
  // The service worker must forward it so Python can answer 404; dropping it
  // here would look like a network error instead of an invalidated cache.
  const parsed = routes.parseZarrPath(fixtures.stale_request.path);
  assert.equal(parsed.route, fixtures.stale_request.route);
});

test("the viewer iframe is not treated as an app page", () => {
  // The Neuroglancer iframe is a window client of the same scope, but it has
  // no handler for the service worker's messages: sending it a chunk request
  // means waiting for a reply that never arrives, which stalls the viewer
  // exactly when it is fetching most.
  const scope = "http://localhost:8000/browser/";

  assert.equal(routes.isAppPage(`${scope}`, scope), true);
  assert.equal(routes.isAppPage(`${scope}index.html`, scope), true);
  assert.equal(routes.isAppPage(`${scope}index.html?x=1`, scope), true);

  assert.equal(routes.isAppPage(`${scope}neuroglancer/index.html`, scope), false);
  assert.equal(
    routes.isAppPage(`${scope}neuroglancer/index.html#!%7B%7D`, scope),
    false,
  );
});

test("app pages are recognised under a sub-path deployment", () => {
  const scope = "https://example.org/multiview-stitcher/main/browser/";

  assert.equal(routes.isAppPage(`${scope}index.html`, scope), true);
  assert.equal(routes.isAppPage(`${scope}neuroglancer/index.html`, scope), false);
});

test("metadata keys are told apart from chunk data", () => {
  // Metadata must be answered by the worker that owns the session; a layer
  // whose .zattrs fails to load has nothing to render, however well the chunk
  // path works.
  for (const key of [".zattrs", ".zgroup", ".zmetadata", "zarr.json", "0/.zarray", "1/.zattrs"]) {
    assert.equal(routes.isMetadataKey(key), true, key);
  }

  for (const key of ["0/0/0/0/0", "1/0/0/3/2", "0/0.0.0.0", ""]) {
    assert.equal(routes.isMetadataKey(key), false, key);
  }
});

test("the build id covers the app, not just the wheel", async (t) => {
  // `docs/browser/packages/` holds build output and is not checked in, so a
  // fresh clone - and CI, which builds its wheel elsewhere - has no manifest
  // to read. The assertions that need one are worth keeping, but not at the
  // cost of a failure that says nothing about the code.
  const { existsSync, readFileSync } = await import("node:fs");
  const path = join(repoRoot, "docs", "browser", "packages", "manifest.json");
  if (!existsSync(path)) {
    t.skip("no manifest; run scripts/build_browser_app.py to check this");
    return;
  }

  const manifest = JSON.parse(readFileSync(path, "utf8"));
  assert.ok(manifest.sha256, "the manifest must carry a wheel checksum");

  // An id derived from the wheel alone would not move when only JavaScript
  // changed, leaving every such fix hidden behind the cached copy of the very
  // file it was meant to replace.
  assert.match(manifest.build, /^[0-9a-f]{12}$/);
  assert.notEqual(
    manifest.build,
    manifest.sha256.slice(0, 12),
    "the build id should not be the wheel checksum on its own",
  );
});

test("the wheel URL changes when the wheel does", async () => {
  // A rebuild of the same commit produces an identically named wheel, and
  // micropip fetches it from inside a worker - where a page reload does not
  // bypass the HTTP cache. Only a changing URL keeps the Python runtime in
  // step with the JavaScript.
  const { readFileSync } = await import("node:fs");
  const app = readFileSync(join(repoRoot, "docs", "browser", "app.js"), "utf8");
  assert.match(app, /packages\/\$\{manifest\.wheel\}\?v=\$\{build\}/);
  // Worker scripts are loaded the same way and need the same treatment.
  for (const worker of ["fs-worker.js", "session-worker.js", "compute-worker.js"]) {
    assert.match(
      app,
      new RegExp(`${worker.replace(".", "\\.")}\\?v=`),
      `${worker} must be cache-busted`,
    );
  }
  assert.match(app, /fetch\("config\.json", noStore\)/);
  assert.match(app, /fetch\("packages\/manifest\.json", noStore\)/);
});

test("a tab owns only the routes of its own session", () => {
  // The service worker asks every open tab and takes the first that does not
  // decline. A tab with no session must decline everything: otherwise it
  // answers for another tab's images out of an empty session, and the tab
  // that actually holds the data is never asked.
  assert.equal(routes.ownsRoute("abc123", "abc123/g2/fused.ome.zarr"), true);
  assert.equal(routes.ownsRoute("abc123", "abc123/g9/view_0.ome.zarr"), true);

  assert.equal(routes.ownsRoute("abc123", "other/g2/fused.ome.zarr"), false);
  assert.equal(routes.ownsRoute(null, "abc123/g2/fused.ome.zarr"), false);
  assert.equal(routes.ownsRoute(undefined, "abc123/g2/fused.ome.zarr"), false);
  assert.equal(routes.ownsRoute("", "abc123/g2/fused.ome.zarr"), false);
  assert.equal(routes.ownsRoute("abc123", ""), false);

  // A session id that is a prefix of another must not match it.
  assert.equal(routes.ownsRoute("abc", "abc123/g2/fused.ome.zarr"), false);
});

test("the page loads its own scripts at the build version", async () => {
  // A cached app.js behind a freshly cache-busted wheel means running two
  // halves of different builds, which fails in ways that resemble neither.
  const { readFileSync } = await import("node:fs");
  const html = readFileSync(join(repoRoot, "docs", "browser", "index.html"), "utf8");

  // No unversioned script tags for our own code.
  assert.doesNotMatch(html, /<script src="(routes|app)\.js"><\/script>/);
  assert.match(html, /packages\/manifest\.json", \{ cache: "no-store" \}/);
  assert.match(html, /\$\{src\}\?v=\$\{build\}/);
  for (const src of ["routes.js", "app.js"]) {
    assert.ok(html.includes(`"${src}"`), `${src} must be loaded by the bootstrap`);
  }
});

test("the page starts its workers eagerly and without blocking", async () => {
  // Booting a Pyodide runtime takes seconds; doing it on the first action
  // makes the whole UI wait for something it already knew it would need.
  const { readFileSync } = await import("node:fs");
  const app = readFileSync(join(repoRoot, "docs", "browser", "app.js"), "utf8");

  assert.match(app, /function startWorkers\(\)/);
  // Fired at start-up and on every change of the worker count.
  assert.match(app, /select\.addEventListener\("change", \(\) => \{[\s\S]*?startWorkers\(\);/);
  // Not awaited: the promise is only observed to report failure.
  assert.match(app, /pool\s*\n?\s*\.resize\(requested, state\.runtimeConfig\)\s*\n?\s*\.catch\(/);
  // Work still waits for a pool that is still coming up.
  assert.match(app, /await pool\.ready\(\)/);
});

test("dropped folders are claimed before any await", async () => {
  // A DataTransferItemList is only valid during the event; reading it after a
  // yield returns nothing, so every handle must be claimed synchronously.
  const { readFileSync } = await import("node:fs");
  const app = readFileSync(join(repoRoot, "docs", "browser", "app.js"), "utf8");

  const handler = app.slice(
    app.indexOf('dropzone.addEventListener("drop"'),
    app.indexOf("$(\"#browse\").addEventListener"),
  );

  const claim = handler.indexOf("items.map((item) => item.getAsFileSystemHandle())");
  const firstAwait = handler.indexOf("await ");
  assert.ok(claim > 0, "handles must be claimed from the item list");
  assert.ok(claim < firstAwait, "handles must be claimed before the first await");
  assert.match(handler, /loadDirectories\(directories\)/);
});

test("Neuroglancer is embedded, not framed", async () => {
  const { readFileSync } = await import("node:fs");
  const html = readFileSync(join(repoRoot, "docs", "browser", "index.html"), "utf8");
  const app = readFileSync(join(repoRoot, "docs", "browser", "app.js"), "utf8");

  assert.doesNotMatch(html, /<iframe/i, "the viewer must not be an iframe");
  assert.match(html, /<div id="viewer"/);
  // Its stylesheet came with the iframe before; an embedded viewer needs it.
  assert.match(html, /neuroglancer\/neuroglancer\.css/);

  // The app drives a mounted viewer rather than a document location.
  assert.doesNotMatch(app, /contentWindow/);
  assert.doesNotMatch(app, /neuroglancer\/index\.html/);
  assert.match(app, /viewer\.setState\(ngState\)/);
});

test("Neuroglancer-specific code stays in the viewer module", async () => {
  // The point of the module: upgrading the viewer means reading one file.
  const { readFileSync, readdirSync } = await import("node:fs");
  const dir = join(repoRoot, "docs", "browser");

  for (const name of readdirSync(dir).filter((f) => f.endsWith(".js"))) {
    if (name === "viewer.js") continue;
    const source = readFileSync(join(dir, name), "utf8");
    assert.doesNotMatch(
      source,
      /from "\.\/neuroglancer\//,
      `${name} must not import neuroglancer directly`,
    );
  }

  const viewer = readFileSync(join(dir, "viewer.js"), "utf8");
  assert.match(viewer, /from "\.\/neuroglancer\/neuroglancer\.js"/);

  // Only the public API surface.
  for (const symbol of ["setupDefaultViewer", "StatusMessage"]) {
    assert.ok(viewer.includes(symbol), `${symbol} should be imported`);
  }
  // The required capabilities are all present.
  for (const method of [
    "mount(", "dispose(", "setLayers(", "updateLayers(",
    "setLayerVisibility(", "getPosition(", "onStateChanged(",
    "onPositionChanged(",
  ]) {
    assert.ok(viewer.includes(method), `viewer.js should expose ${method}`);
  }
  assert.match(viewer, /export function withTransform/);
});

test("applying a state keeps the camera, so updates do not reload", async () => {
  const { readFileSync } = await import("node:fs");
  const viewer = readFileSync(join(repoRoot, "docs", "browser", "viewer.js"), "utf8");

  // restoreState on the live viewer, not a fresh mount.
  assert.match(viewer, /viewer\.state\.restoreState\(state\)/);

  // The camera survives because `restoreState` only touches the keys it is
  // given - not because they are copied over. Resetting first would send the
  // camera to the origin, and nothing brings it back when the layer URLs are
  // unchanged, which is what made a transform-key switch render nothing.
  const setState = viewer.slice(
    viewer.indexOf("setState(state, {"),
    viewer.indexOf("// Layers"),
  );
  assert.ok(
    /if \(!preserveView\) viewer\.state\.reset\(\)/.test(setState),
    "the state should only be reset when the caller gives up the view",
  );
  assert.equal(
    (setState.match(/state\.reset\(\)/g) || []).length,
    1,
    "setState should not reset the viewer on the default path",
  );
});

test("the camera is carried across a rebuilt coordinate space", async () => {
  const { readFileSync } = await import("node:fs");
  const viewer = readFileSync(join(repoRoot, "docs", "browser", "viewer.js"), "utf8");

  // Neuroglancer remaps the camera by dimension index when it rebuilds the
  // coordinate space from the layers; the viewer has to correct that by name.
  assert.match(viewer, /coordinateSpace\.changed\.add/);
  assert.match(viewer, /coordinateSpace\.changed\.remove/);
  assert.match(viewer, /carryCameraOver/);
});

test("a transform_key switch patches transforms instead of rebuilding layers", async () => {
  const { readFileSync } = await import("node:fs");
  const app = readFileSync(join(repoRoot, "docs", "browser", "app.js"), "utf8");
  const viewer = readFileSync(join(repoRoot, "docs", "browser", "viewer.js"), "utf8");

  // Restoring a `layers` array clears the layer list and builds every layer
  // again, which loses the shader and its contrast range, the selected layer
  // and the chosen layout. When only the transforms changed, they are applied
  // to the loaded sources instead.
  assert.match(app, /setLayerTransforms\(/);
  assert.match(viewer, /setLayerTransforms\(transforms\)/);
  // The transform of a loaded source is separately watchable.
  assert.match(viewer, /loadState\.transform\.restoreState/);
  // A source that has not loaded yet gets the transform when it arrives.
  assert.match(viewer, /dataSource\.changed\.add/);
});

test("every call into Python can suspend, and they are taken one at a time", async () => {
  const { readFileSync } = await import("node:fs");
  const runtime = readFileSync(
    join(repoRoot, "docs", "browser", "py-runtime.js"), "utf8",
  );
  const session = readFileSync(
    join(repoRoot, "docs", "browser", "session-worker.js"), "utf8",
  );
  const compute = readFileSync(
    join(repoRoot, "docs", "browser", "compute-worker.js"), "utf8",
  );

  // zarr v3 has no thread to run an event loop on, so it blocks by stack
  // switching - which only works if the call into Python was made in a way
  // that permits it. A plain call raises "Cannot stack switch because the
  // Python entrypoint was a synchronous function".
  for (const entry of ["handle_json", "run_task_json", "serve_route"]) {
    assert.match(
      runtime,
      new RegExp(`${entry}\\.callPromising\\(`),
      `${entry} must be called so it can suspend`,
    );
  }

  // Suspending returns control to the event loop mid-call, so without this a
  // second message would enter Python while the first is still inside it -
  // against a session that is not written to be re-entered.
  assert.match(runtime, /let pythonTurn = Promise\.resolve\(\)/);
  for (const call of ["callCommand", "callTask", "callServe"]) {
    const start = runtime.indexOf(`function ${call}(`);
    const body = runtime.slice(start, runtime.indexOf("\n}", start));
    assert.match(body, /inTurn\(/, `${call} must take its turn`);
  }

  // And the callers have to await what is now a promise.
  assert.match(session, /await callCommand\(/);
  assert.match(session, /await callServe\(/);
  assert.match(compute, /await callTask\(/);
  assert.match(compute, /await callServe\(/);
});

test("the workers are ES modules, because Pyodide refuses classic ones", async () => {
  const { readFileSync } = await import("node:fs");
  const dir = join(repoRoot, "docs", "browser");
  const app = readFileSync(join(dir, "app.js"), "utf8");
  const runtime = readFileSync(join(dir, "py-runtime.js"), "utf8");

  // Pyodide 314 throws "Classic web workers are not supported" on start-up,
  // so the whole chain has to be modules: the Worker, the script it loads,
  // and the way that script pulls in Pyodide.
  assert.match(app, /new Worker\(url, \{ type: "module" \}\)/);
  assert.match(runtime, /await import\(\s*\/\* webpackIgnore: true \*\/ `\$\{config\.pyodide_index_url\}pyodide\.mjs`/);

  for (const worker of ["session-worker.js", "compute-worker.js", "fs-worker.js"]) {
    const source = readFileSync(join(dir, worker), "utf8");
    assert.doesNotMatch(
      source,
      /importScripts\(/,
      `${worker} must not use importScripts`,
    );
  }

  // The two Python workers take their runtime by import, and the names have
  // to be ones py-runtime actually exports.
  for (const [worker, names] of [
    ["session-worker.js", ["bootRuntime", "callCommand", "callServe"]],
    ["compute-worker.js", ["bootRuntime", "callTask", "callServe"]],
  ]) {
    const source = readFileSync(join(dir, worker), "utf8");

    // Started, not awaited. The app posts "boot" the moment it constructs the
    // Worker; a handler installed after a *top-level* await is not there yet
    // when that message arrives, and the worker then sits forever having
    // missed the only message it was sent - which is exactly what happened.
    assert.match(
      source,
      /const runtime = import\(`\.\/py-runtime\.js\$\{self\.location\.search\}`\);/,
      `${worker} must start the import without awaiting it`,
    );
    const beforeHandler = source.slice(0, source.indexOf("self.onmessage"));
    assert.doesNotMatch(
      beforeHandler,
      /\bawait\b/,
      `${worker} must install its message handler before any top-level await`,
    );

    for (const name of names) {
      assert.match(
        runtime,
        new RegExp(`export (async )?(function|let) ${name}\\b`),
        `py-runtime must export ${name} for ${worker}`,
      );
    }
  }
});

test("zarr comes from Pyodide's index, not PyPI", async () => {
  const { readFileSync } = await import("node:fs");
  const config = JSON.parse(
    readFileSync(join(repoRoot, "docs", "browser", "config.json"), "utf8"),
  );

  // Two wheels call themselves the same zarr version. Pyodide's own build
  // suspends the WebAssembly stack; PyPI's starts a thread, which the browser
  // cannot give it - every read then fails with "can't start new thread".
  assert.ok(
    config.pyodide_packages.includes("zarr"),
    "zarr must be loaded from Pyodide's package index",
  );
  assert.ok(
    !config.browser_dependencies.some((dep) => dep.startsWith("zarr")),
    "zarr must not be installed from PyPI by micropip",
  );
});

test("the Python runtime is fetched once, not once per worker", async () => {
  const { readFileSync } = await import("node:fs");
  const sw = readFileSync(join(repoRoot, "docs", "browser", "sw.js"), "utf8");

  // Every worker installs the same ~60 MB runtime and they boot together, so
  // without a cache and single-flight the same bytes are fetched once per
  // worker.
  assert.match(sw, /RUNTIME_CACHE/);
  assert.match(sw, /inFlight/);
  assert.match(sw, /caches\.open\(RUNTIME_CACHE\)/);
  // Cross-origin runtime assets are intercepted; everything else is not.
  assert.match(sw, /RUNTIME_ASSET\.test\(url\.pathname\)/);
  assert.match(sw, /url\.origin !== self\.location\.origin/);

  // itk-wasm ships its pipelines zstd-compressed, so elastix arrives as
  // `elastix.wasm.zst` - a 2.4 MB file every registering worker asks for.
  const pattern = new RegExp(
    sw.match(/const RUNTIME_ASSET = (\/.*\/);/)[1].slice(1, -1),
  );
  assert.ok(pattern.test("/npm/@itk-wasm/elastix/dist/pipelines/elastix.wasm.zst"));
  assert.ok(pattern.test("/pyodide/v314.0.4/full/numpy.whl"));
  assert.ok(!pattern.test("/some/image.png"));
});

test("the shipped pyodide lockfile drops the dependency nothing imports", async () => {
  const { readFileSync, existsSync } = await import("node:fs");
  const lockPath = join(
    repoRoot, "docs", "browser", "packages", "pyodide-lock.json",
  );
  if (!existsSync(lockPath)) return; // built artifact; absent in a fresh clone

  const lock = JSON.parse(readFileSync(lockPath, "utf8"));
  // Pyodide declares matplotlib a dependency of networkx, which drags ~10 MB
  // of it and its font stack into every worker for a module nothing calls.
  assert.ok(lock.packages.networkx, "networkx should be in the lockfile");
  assert.ok(
    !lock.packages.networkx.depends.includes("matplotlib"),
    "matplotlib should not be pulled in via networkx",
  );
  // Only the dependency graph is trimmed; packages themselves are untouched.
  assert.ok(lock.packages.matplotlib, "matplotlib itself should still exist");
  assert.ok(Object.keys(lock.packages).length > 100);
});

test("a custom pyodide lockfile is loaded with an explicit package base", async () => {
  const { readFileSync } = await import("node:fs");
  const runtime = readFileSync(
    join(repoRoot, "docs", "browser", "py-runtime.js"), "utf8",
  );

  // Pyodide defaults `packageBaseUrl` to the directory the lockfile came
  // from. Ours is served from `packages/`, so without an explicit base every
  // wheel is looked for there - producing a wall of SRI failures and a
  // runtime with no micropip, nowhere near the lockfile that caused it.
  if (runtime.includes("lockFileURL")) {
    assert.match(
      runtime,
      /packageBaseUrl:\s*config\.pyodide_index_url/,
      "lockFileURL must be accompanied by packageBaseUrl",
    );
  }
});

test("layers are addressed by the URL they read, not by their name", async () => {
  const { readFileSync } = await import("node:fs");
  const viewer = readFileSync(join(repoRoot, "docs", "browser", "viewer.js"), "utf8");
  const app = readFileSync(join(repoRoot, "docs", "browser", "app.js"), "utf8");

  // Neuroglancer renames layers it opens: an OME-Zarr carrying omero metadata
  // turns "0: tile.ome.zarr" into "0: tile.ome.zarr channel 0". A lookup by
  // name then misses, the in-place update throws, and the app falls back to
  // applying the whole state - resetting the layout and refetching the data.
  // The source URL is the app's own handle and survives the rename.
  assert.match(viewer, /dataSource\.spec\?\.url === url/);
  assert.match(app, /transforms\[url\]/);
  assert.match(app, /visibility\[url\]/);

  // The name must not be what either side matches on.
  const patchPath = viewer.slice(
    viewer.indexOf("setLayerTransforms(transforms)"),
    viewer.indexOf("updateLayers(patches)"),
  );
  assert.ok(
    !/wanted\.has\(managed\.name\)|\.get\(managed\.name\)/.test(patchPath),
    "setLayerTransforms must not look layers up by name",
  );
});

test("clearing gives a genuinely fresh viewer", async () => {
  const { readFileSync } = await import("node:fs");
  const viewer = readFileSync(join(repoRoot, "docs", "browser", "viewer.js"), "utf8");
  const app = readFileSync(join(repoRoot, "docs", "browser", "app.js"), "utf8");

  const reset = viewer.slice(viewer.indexOf("  reset() {"));

  // Emptying the layer list is not enough: Neuroglancer keeps the combined
  // coordinate space, so the next dataset is measured in the previous one's
  // dimensions and bounds. The viewer is rebuilt instead.
  assert.match(reset, /this\.dispose\(\);/);
  assert.match(reset, /this\.mount\(target\);/);

  // A new instance restores from the URL fragment on the way up, which would
  // bring the discarded dataset straight back.
  assert.match(reset, /location\??\.hash/);
  assert.match(reset, /replaceState/);

  // The page resets on clear, and when a load has nothing in common with
  // what is on screen.
  assert.match(app, /if \(viewer\.mounted\) viewer\.reset\(\);/);
  assert.match(app, /!wanted\.some\(\(url\) => known\.includes\(url\)\)/);
  assert.match(app, /viewer\.reset\(\);\n\s*state\.layerSources = sources;/);
});

test("adding the fused preview leaves the rest of the viewer alone", async () => {
  const { readFileSync } = await import("node:fs");
  const viewer = readFileSync(join(repoRoot, "docs", "browser", "viewer.js"), "utf8");
  const app = readFileSync(join(repoRoot, "docs", "browser", "app.js"), "utf8");

  // Restoring a `layers` array clears the layer list and rebuilds every
  // layer, replacing the chosen layout, the selected layer and each layer's
  // shader and contrast range. A layer that appears or disappears is applied
  // on its own instead.
  assert.match(viewer, /addLayers\(specs\)/);
  assert.match(viewer, /removeLayers\(urls\)/);
  assert.match(viewer, /makeLayer\(viewer\.layerSpecification, spec\.name, spec\)/);
  assert.match(viewer, /layerManager\.removeManagedLayer\(managed\)/);

  assert.match(app, /viewer\.removeLayers\(removed\)/);
  assert.match(app, /viewer\.addLayers\(added\)/);

  // A layer added a moment ago has no loaded source to re-aim yet, so only
  // the ones that were already there are patched.
  assert.match(app, /known\.includes\(url\)/);
});

