test("a placement can be pinned to the timepoint on screen", async () => {
  const { readFileSync } = await import("node:fs");
  const html = readFileSync(join(repoRoot, "docs", "browser", "index.html"), "utf8");
  const app = readFileSync(join(repoRoot, "docs", "browser", "app.js"), "utf8");

  assert.match(html, /name="placement-time-mode" value="current"/);
  // A range over every timepoint is what a session starts with, so it is the
  // checked one: an option nobody opens must place tiles as it always did.
  assert.match(html, /name="placement-time-mode" value="range" checked/);

  // Read when the drag is saved rather than when the option was chosen - the
  // timepoint that counts is the one the tile was moved at. `placementTimeRange`
  // is called from the save, so reading `state.timeIndex` there is what makes
  // scrubbing and then dragging place the tile where the drag was seen.
  const range = app.slice(
    app.indexOf("function placementTimeRange()"),
    app.indexOf("function renderPlacementScope"),
  );
  assert.match(range, /placementTimeMode\(\) === "current"/);
  assert.match(range, /return \[index, index\]/);

  // A range slider that no longer says anything does not stay on screen, and
  // the heading follows the viewer while it is the timepoint being named.
  assert.match(app, /row\.hidden = times\.length < 2 \|\| current/);
  const follow = app.slice(
    app.indexOf("function noteTimeIndex()"),
    app.indexOf("/** The layers a state describes"),
  );
  assert.match(follow, /updatePlacementTimeUi\(\)/);
});

test("a transform that varies over time or channel is shown as one sample", async () => {
  const { readFileSync } = await import("node:fs");
  const app = readFileSync(join(repoRoot, "docs", "browser", "app.js"), "utf8");
  const viewer = readFileSync(join(repoRoot, "docs", "browser", "viewer.js"), "utf8");

  // A source transform is one matrix. Over time that means showing the
  // timepoint being viewed, and re-aiming the layers when it moves.
  assert.match(app, /time_index: state\.timeIndex/);
  assert.match(app, /function noteTimeIndex\(\)/);
  assert.match(app, /if \(!state\.timeVaryingTransforms\) return;/);

  // Re-aiming, not rebuilding: a scrub changes which sample of each transform
  // a layer carries and nothing else, so asking for a whole viewer state on
  // every step would take apart every layer, shader and contrast range to say
  // the same thing.
  const follow = app.slice(
    app.indexOf("function noteTimeIndex()"),
    app.indexOf("/** The layers a state describes"),
  );
  assert.match(follow, /refreshTransforms\(\)/);
  assert.ok(
    !/refreshViewer\(\)/.test(follow),
    "following the timepoint must not rebuild the viewer state",
  );
  assert.match(app, /command\("view_transforms"/);
  assert.match(app, /viewer\.setLayerTransforms\(transforms\)/);
  // A drag can only show one timepoint of a placement stored for a range of
  // them, so what the session holds is what ends up on screen.
  assert.match(app, /if \(hadPreview \|\| timeRange\)/);

  // Over channel it means one layer each, aimed separately - which cannot
  // travel inside the state, since the state has one layer per view.
  assert.match(app, /command\("channel_transforms"/);
  assert.match(viewer, /setChannelTransforms\(transforms\)/);

  // Registering a timelapse resolves one transform per timepoint just like a
  // time-scoped manual placement does, so it has to flip the same flag -
  // otherwise the viewer keeps showing the sample it was built with as the
  // user scrubs time, and a registered timelapse looks unregistered past
  // frame zero.
  const register = app.slice(
    app.indexOf("async function doRegister"),
    app.indexOf("async function doFusePreview"),
  );
  assert.match(
    register,
    /if \(timeCoords\(\)\.length > 1\) state\.timeVaryingTransforms = true;/,
  );
});

